"""Best-effort importer for JSON reports generated by MarlonTheBug 1.x."""

from __future__ import annotations

import json
import logging
from datetime import UTC, datetime
from pathlib import Path
from typing import Any
from urllib.parse import urlparse

from marlonthebug.db.repository import Repository, finding_fingerprint

logger = logging.getLogger("marlonthebug.legacy")

ALLOWED_SEVERITIES = {"critical", "high", "medium", "low", "info"}


async def import_reports(repository: Repository, reports_dir: Path) -> dict[str, int]:
    stats = {"reports": 0, "findings": 0, "workspaces": 0, "skipped": 0}
    if not reports_dir.exists():
        return stats
    for path in sorted(reports_dir.glob("*.json")):
        try:
            payload = json.loads(path.read_text(encoding="utf-8"))
        except (OSError, json.JSONDecodeError):
            stats["skipped"] += 1
            continue
        findings = payload.get("findings")
        if not isinstance(findings, list) or not findings:
            stats["skipped"] += 1
            continue
        workspace_name = str(payload.get("workspace") or path.stem)
        workspace = await repository.get_workspace_by_name(workspace_name)
        if not workspace:
            workspace = await repository.create_workspace(
                workspace_name,
                description=f"Importado desde {path.name}",
            )
            stats["workspaces"] += 1
        targets = sorted({_host_for(finding) for finding in findings if _host_for(finding)})
        for host in targets:
            await repository.add_target(workspace.id, host)
        scan = await repository.create_scan(
            workspace_id=workspace.id,
            targets=targets or ["legacy"],
            categories=sorted({str(finding.get("category") or "web") for finding in findings}),
            profile="legacy",
            options={"source": path.name},
            created_by="legacy-import",
        )
        for finding in findings:
            host = _host_for(finding) or "legacy"
            evidence = finding.get("evidence") if isinstance(finding.get("evidence"), dict) else {}
            severity = str(finding.get("severity") or "info").lower()
            if severity not in ALLOWED_SEVERITIES:
                severity = "info"
            title = str(finding.get("title") or "Hallazgo importado")
            endpoint = str(finding.get("endpoint") or "")
            parameter = str(evidence.get("parameter", "")) if isinstance(evidence, dict) else ""
            await repository.upsert_finding(
                {
                    "workspace_id": workspace.id,
                    "scan_run_id": scan.id,
                    "plugin_name": str(finding.get("plugin_name") or "legacy"),
                    "category": str(finding.get("category") or "web"),
                    "title": title,
                    "description": str(finding.get("description") or ""),
                    "severity": severity,
                    "confidence": str(finding.get("confidence") or "medium"),
                    "status": str(finding.get("status") or "open"),
                    "cvss_score": float(finding.get("cvss_score") or 0),
                    "cvss_vector": str(finding.get("cvss_vector") or ""),
                    "cwe": str(finding.get("cwe") or ""),
                    "owasp": str(finding.get("owasp") or ""),
                    "endpoint": endpoint,
                    "target_host": host,
                    "evidence": evidence,
                    "remediation": str(finding.get("remediation") or ""),
                    "references": finding.get("references") or [],
                    "waf_rules": finding.get("waf_rules") or [],
                    "verified": bool(finding.get("verified") or False),
                    "fingerprint": finding_fingerprint(
                        str(finding.get("plugin_name") or "legacy"),
                        title,
                        endpoint,
                        host,
                        parameter,
                    ),
                }
            )
            stats["findings"] += 1
        await repository.update_scan(
            scan.id,
            status="completed",
            started_at=datetime.now(UTC),
            finished_at=datetime.now(UTC),
            stats={"findings": len(findings), "imported": True},
            logs=[
                {
                    "time": datetime.now(UTC).strftime("%H:%M:%S"),
                    "level": "INFO",
                    "message": f"Importado desde {path.name}",
                }
            ],
        )
        stats["reports"] += 1
    return stats


def _host_for(finding: dict[str, Any]) -> str:
    host = str(finding.get("target_host") or "").strip().lower()
    if host:
        return host
    endpoint = str(finding.get("endpoint") or "")
    if not endpoint:
        return ""
    parsed = urlparse(endpoint if "://" in endpoint else f"//{endpoint}")
    return (parsed.hostname or "").lower()
